import SwiftUI
struct LedgerView: View { let store: LedgerStore; @State private var showAdd = false; @State private var filter: TransactionType?; var body: some View { NavigationStack { List { ForEach(store.transactions.filter { filter == nil || $0.type == filter }, id: \.persistentModelID) { tx in HStack { VStack(alignment: .leading) { Text("\(tx.assetName) · \(tx.type.rawValue)").font(.headline); Text(tx.date, format: .dateTime.year().month().day()).font(.caption).foregroundStyle(.secondary) }; Spacer(); Text(tx.amount, format: .number.precision(.fractionLength(2))) } } }.navigationTitle("记账").toolbar { ToolbarItem(placement: .topBarTrailing) { Button("＋") { showAdd = true } } }.sheet(isPresented: $showAdd) { AddTransactionView(store: store) } } }
}
struct AddTransactionView: View { let store: LedgerStore; @Environment(\.dismiss) private var dismiss; @State private var asset = "招商银行"; @State private var type: TransactionType = .buy; @State private var amount = ""; @State private var date = Date.now; var body: some View { NavigationStack { Form { TextField("标的名称", text: $asset); Picker("交易类型", selection: $type) { ForEach(TransactionType.allCases, id: \.self) { Text($0.rawValue).tag($0) } }; TextField("金额", text: $amount).keyboardType(.decimalPad); DatePicker("交易日期", selection: $date, displayedComponents: .date) }.navigationTitle("新增交易").toolbar { ToolbarItem(placement: .cancellationAction) { Button("取消") { dismiss() } }; ToolbarItem(placement: .confirmationAction) { Button("保存") { if let value = Decimal(string: amount), value > 0 { store.add(type: type, asset: asset, amount: value, date: date); dismiss() } } } } } }
}
